package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="page_components")
public class PageComponent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="page_id",nullable=false) private UUID pageId; @Column(name="component_type",nullable=false,length=50) private String componentType; @Column(length=255) private String label; @Column(name="bound_field",length=100) private String boundField; @Column(columnDefinition="text") private String config; @Column(name="display_order",nullable=false) private int displayOrder; @Column(nullable=false,length=20) private String source="manual"; @Column(name="needs_review",nullable=false) private boolean needsReview=false;
 public UUID getId(){return id;} public UUID getPageId(){return pageId;} public void setPageId(UUID v){pageId=v;} public String getComponentType(){return componentType;} public void setComponentType(String v){componentType=v;} public String getLabel(){return label;} public void setLabel(String v){label=v;} public String getBoundField(){return boundField;} public void setBoundField(String v){boundField=v;} public String getConfig(){return config;} public void setConfig(String v){config=v;} public int getDisplayOrder(){return displayOrder;} public void setDisplayOrder(int v){displayOrder=v;} public String getSource(){return source;} public void setSource(String v){source=v;} public boolean isNeedsReview(){return needsReview;} public void setNeedsReview(boolean v){needsReview=v;}
}
